import { async, ComponentFixture, TestBed } from '@angular/core/testing';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';
import { ReactiveFormsModule } from '@angular/forms';
import { RouterTestingModule } from '@angular/router/testing';

import { SharedModule } from '@nusantara/shared';
import { CategoryComponent } from '@nusantara/pages/catalog/category';

describe('CategoryComponent', () => {
  let component: CategoryComponent;
  let fixture: ComponentFixture<CategoryComponent>;

  let httpTestingController: HttpTestingController;

  const categoryCreateNewResp = {
    name: 'test add new category',
    pathName: '',
    productCount: 0,
    depth: 1,
    sourceMappings: ['Hi',
      'Yes this is another mapping.'],
    href: 'https://staging.bhisma.cloud/api/catalog/category/test-add-category/',
    image: 'https://staging-cdn.bhisma.cloud/catalog/category/ec7b68df-ad06-4f86-a2b3-96853b1129f8.png',
    parent: null
  };

  const image64 = '';
  const categoryUpdateResp = {
    name: 'test update category',
    pathName: 'can you update meh',
    productCount: 0,
    depth: 1,
    sourceMappings: ['Hallo',
      'Yes this is another mapping.'],
    href: 'https://staging.bhisma.cloud/api/catalog/category/test-add-category/',
    image: null,
    parent: 'https://staging.bhisma.cloud/api/catalog/category/body-care-7/'
  };

  beforeEach(async(() => {
    TestBed.configureTestingModule({
      imports: [
        HttpClientTestingModule,
        ReactiveFormsModule,
        RouterTestingModule,
        SharedModule
      ],
      declarations: [
        CategoryComponent,
      ],
      providers: []
    })
      .compileComponents();
  }));

  beforeEach(() => {
    httpTestingController = TestBed.inject(HttpTestingController);
    fixture = TestBed.createComponent(CategoryComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('should create', () => {
    expect(component).toBeTruthy();
  });

  it('form invalid when empty', () => {
    component.form.controls.name.setValue('');
    component.form.controls.href.setValue('');
    component.form.controls.image.setValue('');
    component.form.controls.parent.setValue('');
    component.form.controls.sourceMappings.setValue([]);
    expect(component.form.valid).toBeFalsy();
  });

  it('name field validity', () => {
    const name = component.form.controls.name;
    expect(name.valid).toBeFalsy();

    name.setValue('');
    expect(name.hasError('required')).toBeTruthy();
  });

  it('can create a new category', () => {

    component.form.setValue({
      name: categoryCreateNewResp.name,
      sourceMappings: [],
      href: '',
      image: '',
      parent: categoryCreateNewResp.parent
    });
    // @ts-ignore
    const sm1 = component.fb.control(categoryCreateNewResp.sourceMappings[0]);
    // @ts-ignore
    const sm2 = component.fb.control(categoryCreateNewResp.sourceMappings[1]);
    component.sourceMappings.push(sm1);
    component.sourceMappings.push(sm2);
    component.form.value.image = image64;
    component.save();

    const mock = httpTestingController.expectOne('/api/catalog/category/');
    expect(mock.request.method).toEqual('POST');
    expect(mock.request.body.name).toBe(categoryCreateNewResp.name);
    expect(mock.request.body.sourceMappings).toEqual(categoryCreateNewResp.sourceMappings);
    expect(mock.request.body.image).toEqual(image64);
    expect(mock.request.body.parent).toEqual(null);
    mock.flush(categoryCreateNewResp, ({status: 201, statusText: 'CREATED'}));
    httpTestingController.verify();
  });

  it('can edit a category', () => {

    component.form.setValue({
      name: categoryUpdateResp.name,
      sourceMappings: [],
      href: categoryUpdateResp.href,
      image: '',
      parent: categoryUpdateResp.parent
    });
    // @ts-ignore
    const sm1 = component.fb.control(categoryUpdateResp.sourceMappings[0]);
    // @ts-ignore
    const sm2 = component.fb.control(categoryUpdateResp.sourceMappings[1]);
    component.sourceMappings.push(sm1);
    component.sourceMappings.push(sm2);
    component.save();

    const mock = httpTestingController.expectOne(categoryUpdateResp.href);
    expect(mock.request.method).toEqual('PATCH');
    expect(mock.request.body.name).toBe(categoryUpdateResp.name);
    expect(mock.request.body.sourceMappings).toEqual(categoryUpdateResp.sourceMappings);
    expect(mock.request.body.image).toEqual('');
    expect(mock.request.body.parent).toEqual(categoryUpdateResp.parent);
    mock.flush(categoryUpdateResp, ({status: 200, statusText: 'OK'}));
    httpTestingController.verify();
  });

  it('can delete category', () => {
    component.href.setValue(categoryUpdateResp.href);
    component.delete();

    const mock = httpTestingController.expectOne(categoryUpdateResp.href);
    expect(mock.request.method).toEqual('DELETE');
    mock.flush(null, {status: 204, statusText: 'No Content'});
    httpTestingController.verify();
  });
});
